head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // target 생성 (padding, border, margin 을 설정하여 sizeName 별 반환값 구분)
    let grp_comp = $c.gcm.getTestGroup();

    let strTarget = scwin.getSwitchMarkup('style="position:relative; width:500px; height:240px; padding:5px; border:1px solid black; margin:5px;"');

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "switch",
        strTarget,
        grp_comp
    );

    // 탭 헤더 생성 (switch 앞)
    await scwin.createSwitchTab(scwin.target1, scwin.target1);
};


// switch 마크업 생성 : case1 기본정보 / case2 연락처 / case3 이용 안내 (case, 자식 ID 는 자동 부여 → 재생성 시 중복 ID 방지)
scwin.getSwitchMarkup = function (strAttr) {
    let strNameSpace = $c.gcm.getNameSpace();
    let strCaseStyle = 'position:absolute; top:0px; left:0px; width:100%; height:100%; padding:12px 16px; border:1px solid #c9d1db; border-top:none; box-sizing:border-box;';

    let fnTitle = function (label) {
        return '<w2:textbox id="" label="' + label + '" style="height:30px; line-height:30px; font-weight:bold; border-bottom:1px solid #cccccc; margin-bottom:6px;"></w2:textbox>';
    };

    let fnRow = function (label, value) {
        let strRow = '';
        strRow += '<xf:group id="" style="height:34px; display:flex; align-items:center;">';
        strRow += '<w2:textbox id="" label="' + label + '" style="width:80px; height:21px; line-height:21px;"></w2:textbox>';
        strRow += '<xf:input id="" style="width:300px; height:21px;" initValue="' + value + '"></xf:input>';
        strRow += '</xf:group>';
        return strRow;
    };

    let strTarget = '';
    strTarget += '<xf:switch ' + strNameSpace + ' id="" ' + strAttr + '>';

    // case1 : 기본정보 입력 폼
    strTarget += '<xf:case id="" style="' + strCaseStyle + '">';
    strTarget += fnTitle('기본정보');
    strTarget += fnRow('이름', '홍길동');
    strTarget += fnRow('생년월일', '1990-01-15');
    strTarget += fnRow('부서', '개발팀');
    strTarget += '<xf:group id="" style="height:40px; margin-top:8px; padding-left:80px; display:flex; align-items:center;">';
    strTarget += '<w2:button id="" style="width:80px; height:23px;" label="저장"></w2:button>';
    strTarget += '</xf:group>';
    strTarget += '</xf:case>';

    // case2 : 연락처 입력 폼
    strTarget += '<xf:case id="" style="' + strCaseStyle + '">';
    strTarget += fnTitle('연락처');
    strTarget += fnRow('이메일', 'hong@inswave.com');
    strTarget += fnRow('휴대폰', '010-1234-5678');
    strTarget += fnRow('주소', '서울특별시 강남구 테헤란로 123');
    strTarget += '</xf:case>';

    // case3 : 이용 안내 문구
    strTarget += '<xf:case id="" style="' + strCaseStyle + '">';
    strTarget += fnTitle('이용 안내');
    strTarget += '<xf:group id="" style="width:100%; padding:8px; border:1px solid #cccccc; background-color:#f7f7f7; box-sizing:border-box;">';
    let arrGuide = [
        '1. 기본정보 탭 : 이름, 생년월일, 부서를 입력합니다.',
        '2. 연락처 탭 : 이메일, 휴대폰, 주소를 입력합니다.',
        '3. 상단 탭 버튼을 누르면 해당 화면으로 전환됩니다.',
        '4. 입력한 값은 탭을 전환해도 유지됩니다.'
    ];
    for (let i = 0; i < arrGuide.length; i++) {
        strTarget += '<w2:textbox id="" label="' + arrGuide[i] + '" style="height:22px; line-height:22px;"></w2:textbox>';
    }
    strTarget += '</xf:group>';
    strTarget += '</xf:case>';

    strTarget += '</xf:switch>';

    return strTarget;
};



// 탭 헤더 생성 (grp_switchTab : btn_case1~3) → objBefore 앞으로 이동, 선택된 case 의 탭 강조
scwin.createSwitchTab = async function (objSwitch, objBefore) {
    // 기존 탭 헤더 삭제 (Target 재생성 시 중복 방지)
    let arrTabID = ['btn_case1', 'btn_case2', 'btn_case3', 'grp_switchTab'];
    for (let i = 0; i < arrTabID.length; i++) {
        let objTab = $p.getComponentById(arrTabID[i]);
        if (objTab)
            objTab.remove();
    }

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    let strTab = '<xf:group ' + strNameSpace + ' id="" style="width:500px; height:32px; display:flex; align-items:flex-end; gap:2px; border-bottom:2px solid #3d7eff; box-sizing:border-box;"></xf:group>';
    scwin.grp_switchTab = await $p.dynamicCreate("grp_switchTab", "group", strTab, grp_comp);

    let arrTabLabel = ['기본정보', '연락처', '이용안내'];
    let arrTabBtn = [];
    for (let i = 0; i < arrTabLabel.length; i++) {
        let strBtn = '<w2:button ' + strNameSpace + ' id="" style="width:100px; height:30px; border:1px solid #c9d1db; border-bottom:none; border-radius:4px 4px 0px 0px;" label="' + arrTabLabel[i] + '" ev:onclick="scwin.btn_case' + (i + 1) + '_onclick"></w2:button>';
        scwin['btn_case' + (i + 1)] = await $p.dynamicCreate('btn_case' + (i + 1), "button", strBtn, scwin.grp_switchTab);
        arrTabBtn.push(scwin['btn_case' + (i + 1)]);
    }

    if (objBefore && objBefore.render && objBefore.render.parentNode)
        objBefore.render.parentNode.insertBefore(scwin.grp_switchTab.render, objBefore.render);

    let fnSyncTab = function () {
        let idx = objSwitch.getSelectedIndex();
        for (let i = 0; i < arrTabBtn.length; i++) {
            let objStyle = arrTabBtn[i].render.style;
            let isSelected = (i === idx);
            objStyle.backgroundColor = isSelected ? '#3d7eff' : '#eef1f5';
            objStyle.borderColor = isSelected ? '#3d7eff' : '#c9d1db';
            objStyle.color = isSelected ? '#ffffff' : '#555555';
            objStyle.fontWeight = isSelected ? 'bold' : 'normal';
        }
    };

    let observer = new MutationObserver(fnSyncTab);
    observer.observe(objSwitch.render, { attributes: true, attributeFilter: ['style'], subtree: true });
    fnSyncTab();
};



scwin.btn_case1_onclick = function (e) {
    scwin.target1.setSelectedIndex(0);
};



scwin.btn_case2_onclick = function (e) {
    scwin.target1.setSelectedIndex(1);
};



scwin.btn_case3_onclick = function (e) {
    scwin.target1.setSelectedIndex(2);
};
